import openpyxl
inp = openpyxl.load_workbook('/tmp/llm_rollout_vxgjyqek/3_3048_answer_template_6793_input.xlsx', data_only=False)
gld = openpyxl.load_workbook('/mnt/hhq/data/data_pipeline/generated_tasks/route_b_answer_files_batch1/passed/template/3_3048_answer_template_6793_golden.xlsx', data_only=False)
for name in ['DATA 1','SUB']:
    a = inp[name]; b = gld[name]
    print('===', name, '===')
    # formulas
    for row in a.iter_rows():
        for c in row:
            if isinstance(c.value, str) and c.value.startswith('='):
                if b[c.coordinate].value != c.value:
                    print('FORMULA DIFF', c.coordinate, repr(c.value), repr(b[c.coordinate].value))
    # styles compare cell by cell
    for row in a.iter_rows():
        for c in row:
            ac = c; bc = b[c.coordinate]
            if ac.style_id != bc.style_id:
                print('STYLE DIFF', c.coordinate, ac.style_id, bc.style_id)
    print('merged a', a.merged_cells.ranges, 'b', b.merged_cells.ranges)
